
.companion-card {
  padding: 26px 22px 22px;
  position: relative;
}

.corner {
  position: absolute;
  width: 22px;
  height: 22px;
  border: 2px solid rgba(200, 149, 92, 0.5);
  pointer-events: none;
}

.corner-tl {
  top: 10px;
  left: 10px;
  border-right: none;
  border-bottom: none;
}

.corner-br {
  bottom: 10px;
  right: 10px;
  border-left: none;
  border-top: none;
}

.companion-head {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
  padding-bottom: 12px;
  border-bottom: 2px dashed #e4d4ba;
}

.head-icon {
  color: #c8955c;
  flex-shrink: 0;
}

.companion-eyebrow {
  margin: 0 0 4px;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: #a88a6d;
}

.companion-title {
  margin: 0;
  font-size: 1.45rem;
  font-weight: 900;
  color: #4a3b32;
}

.mode-row {
  display: flex;
  gap: 8px;
  margin-bottom: 14px;
}

.mode-chip {
  flex: 1;
  padding: 10px 12px;
  border: 2px solid #e4d4ba;
  border-radius: 12px;
  background: #fffdf8;
  color: #5c4738;
  font-size: 0.84rem;
  font-weight: 900;
  font-family: inherit;
  cursor: pointer;

  &.selected {
    border-color: #7ca982;
    background: #f4faf5;
    box-shadow: 0 0 0 2px rgba(124, 169, 130, 0.18);
  }
}

.scroll-area {
  max-height: min(58vh, 420px);
  overflow-y: auto;
  overflow-x: hidden;
  padding-right: 4px;
  margin-bottom: 14px;
}

.npc-card {
  margin-bottom: 14px;
  padding: 14px;
  border: 2px dashed #e4d4ba;
  border-radius: 14px;
  background: rgba(255, 253, 248, 0.85);
}

.npc-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.npc-card-title {
  margin: 0;
  font-size: 0.9rem;
  font-weight: 900;
  color: #5c4738;
}

.remove-btn {
  border: none;
  background: transparent;
  color: #d9776c;
  font-size: 0.72rem;
  font-weight: 800;
  font-family: inherit;
  cursor: pointer;
}

.npc-profile-row {
  display: flex;
  gap: 14px;
  margin-bottom: 10px;
}

.avatar-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex-shrink: 0;
}

.avatar-picker {
  width: 96px;
  height: 96px;
  border-radius: 18px;
  background: #dcd1be;
  border: 3px solid #c8955c;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  overflow: hidden;
  position: relative;
  box-shadow: 0 2px 8px rgba(92, 71, 56, 0.1);
}

.avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.avatar-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(145deg, #efe6d8 0%, #dcd1be 100%);
}

.avatar-letter {
  font-size: 2rem;
  font-weight: 900;
  color: #5c4738;
}

.avatar-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  color: #fff;
  font-size: 0.82rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  transition: background 0.2s ease;
}

.avatar-picker:hover .avatar-overlay {
  background: rgba(0, 0, 0, 0.55);
}

.hidden-input {
  display: none;
}

.profile-fields {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  justify-content: center;
}

.field-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.field-block {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.span-2 {
  grid-column: span 2;
}

.field-label {
  font-size: 0.72rem;
  font-weight: 800;
  color: #c8955c;
}

.field-input,
.field-textarea {
  width: 100%;
  padding: 9px 11px;
  border: 2px solid #e4d4ba;
  border-radius: 10px;
  background: #fffdf8;
  color: #5c4738;
  font-size: 0.82rem;
  font-weight: 700;
  font-family: inherit;
  line-height: 1.5;
  box-sizing: border-box;

  &:focus {
    outline: none;
    border-color: #7ca982;
    box-shadow: 0 0 0 2px rgba(124, 169, 130, 0.2);
  }
}

.field-textarea {
  resize: vertical;
}

.skills-block {
  margin-top: 2px;
}

.skills-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.skill-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.72rem;
  font-weight: 800;
  color: #8c7462;
}

.skill-input {
  padding: 8px 10px;
}

.add-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  justify-content: center;
  padding: 11px 14px;
  border: 2px dashed #c8955c;
  border-radius: 12px;
  background: #fffaf2;
  color: #8c7462;
  font-size: 0.82rem;
  font-weight: 800;
  font-family: inherit;
  cursor: pointer;

  &:hover {
    border-color: #7ca982;
    color: #5c4738;
  }
}

.none-hint {
  margin: 0 0 14px;
  padding: 12px 14px;
  border-radius: 12px;
  background: #f4faf5;
  border: 2px solid #d8e8da;
  font-size: 0.78rem;
  font-weight: 700;
  color: #6b4c3a;
  line-height: 1.55;
}

.companion-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-top: 4px;
  border-top: 2px dashed #e4d4ba;
}

.ghost-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 11px 14px;
  border: 2px solid #e4d4ba;
  border-radius: 12px;
  background: #fcf8f0;
  color: #8c7462;
  font-size: 0.82rem;
  font-weight: 800;
  font-family: inherit;
  cursor: pointer;

  &:hover {
    border-color: #d4c2a4;
    color: #5c4738;
  }
}

.companion-enter-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 13px 22px;
  font-size: 0.92rem;
  font-weight: 900;
  font-family: inherit;
  border: 2px solid #c8955c;
  border-radius: 12px;
  background: linear-gradient(180deg, #f0c999 0%, #e6b981 45%, #d9a86a 100%);
  color: #634326;
  box-shadow: 0 4px 0 #c8955c, inset 0 1px 0 rgba(255, 255, 255, 0.35);
  cursor: pointer;

  &:disabled {
    opacity: 0.75;
    cursor: wait;
  }
}

.error-text {
  margin: 10px 0 0;
  font-size: 0.78rem;
  font-weight: 700;
  color: #d9776c;
  text-align: center;
}
