
.panel-page {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding-bottom: 16px;
  min-width: 0;
  container-type: inline-size;
  container-name: camp-panel;
}

.title-icon {
  color: #c8955c;
}

.stat-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  min-width: 0;
}

.population-card {
  grid-column: 1 / -1;
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.population-head {
  display: flex;
  align-items: center;
  gap: 12px;
}

.population-total {
  margin: 0;
  font-size: 1.75rem;
  font-weight: 900;
  color: #4a3b32;
  line-height: 1.1;
}

.population-label {
  margin: 4px 0 0;
  font-size: 0.72rem;
  font-weight: 700;
  color: #8c7462;
  letter-spacing: 0.04em;
}

.population-breakdown {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: 8px;
}

.population-breakdown li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.45);
  border: 1px solid #e4d4ba;
}

.population-race {
  font-size: 0.82rem;
  font-weight: 800;
  color: #5c4738;
}

.population-count {
  font-size: 0.82rem;
  font-weight: 900;
  color: #6b8f71;
}

@container camp-panel (min-width: 520px) {
  .stat-grid {
    grid-template-columns: minmax(180px, 1.35fr) repeat(3, minmax(0, 1fr));
  }

  .population-card {
    grid-column: auto;
    grid-row: span 1;
  }
}

.icon-people {
  color: #5c4738;
}

.icon-food {
  color: #e07a5f;
}

.icon-shelter {
  color: #7ca982;
}

.icon-cohesion {
  color: #d9776c;
}

.survival-dashboard {
  margin-bottom: 0;
  padding: 16px 18px;
}

.camp-overview-block {
  margin-bottom: 14px;
}

.camp-overview-title,
.countdown-title {
  margin: 0 0 10px;
  font-size: 0.88rem;
  font-weight: 900;
  color: #5c4738;
}

.camp-overview-grid,
.countdown-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.camp-overview-cell,
.countdown-card {
  background: rgba(255, 255, 255, 0.45);
  border: 1px solid #e4d4ba;
  border-radius: 12px;
  padding: 12px;
}

.camp-overview-cell .stat-label {
  font-size: 0.72rem;
  font-weight: 800;
  color: #8c7462;
  margin-bottom: 4px;
}

.camp-overview-cell .stat-value {
  font-size: 0.92rem;
  font-weight: 900;
  color: #4a3b32;
  line-height: 1.35;
}

.highlight-cell .stat-value {
  color: #a8543f;
}

.countdown-block {
  margin-bottom: 14px;
}

.countdown-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.countdown-label {
  font-size: 0.72rem;
  font-weight: 800;
  color: #8c7462;
}

.countdown-value {
  font-size: 0.95rem;
  font-weight: 900;
  color: #4a3b32;
}

.countdown-card.tone-active {
  border-color: #e07a5f;
  background: #fff5f3;
}

.countdown-card.tone-active .countdown-value {
  color: #a8543f;
}

.countdown-card.tone-soon {
  border-color: #e6b981;
  background: #fff8ef;
}

.countdown-card.tone-soon .countdown-value {
  color: #8a5a20;
}

@media (max-width: 560px) {
  .camp-overview-grid,
  .countdown-grid {
    grid-template-columns: 1fr;
  }
}

.survival-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.survival-card {
  padding: 14px 16px;
  border-radius: 14px;
  border: 2px solid #e4d4ba;
  background: #fdfbf7;

  &.status-充足 {
    border-color: #8fc0a9;
    background: #f3faf5;
  }

  &.status-紧张,
  &.status-偏低 {
    border-color: #e6b981;
    background: #fff8ef;
  }

  &.status-危急,
  &.status-断粮,
  &.status-告急,
  &.status-熄灭 {
    border-color: #e8a598;
    background: #fff5f3;
  }
}

.survival-card-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.survival-card-title {
  flex: 1;
  font-size: 0.82rem;
  font-weight: 900;
  color: #5c4738;
}

.survival-badge {
  font-size: 0.68rem;
  font-weight: 900;
  padding: 3px 8px;
  border-radius: 999px;
  background: #efe6d8;
  color: #6b4c3a;
}

.survival-icon {
  flex-shrink: 0;

  &.food {
    color: #e07a5f;
  }

  &.fuel {
    color: #c8955c;
  }
}

.survival-main {
  margin: 0 0 6px;
  font-size: 1.15rem;
  font-weight: 900;
  color: #3d5c45;
}

.survival-meta {
  margin: 0;
  font-size: 0.72rem;
  font-weight: 700;
  color: #6b4c3a;
  line-height: 1.45;

  &.subtle {
    margin-top: 4px;
    color: #8c7462;
  }
}

.survival-warnings {
  list-style: none;
  margin: 14px 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.survival-warning {
  padding: 10px 12px;
  border-radius: 10px;
  font-size: 0.76rem;
  font-weight: 700;
  line-height: 1.45;

  &.level-danger {
    background: #fde8e4;
    color: #9b3d32;
    border-left: 4px solid #d9776c;
  }

  &.level-warn {
    background: #fff3e0;
    color: #8a5a20;
    border-left: 4px solid #e6b981;
  }

  &.level-info {
    background: #eef4f0;
    color: #3d5c45;
    border-left: 4px solid #8fc0a9;
  }
}

@media (max-width: 520px) {
  .survival-grid {
    grid-template-columns: 1fr;
  }
}

.camp-layout {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 20px;
  min-width: 0;
}

.camp-side {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.section {
  padding: 22px;
}

.section-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 18px;

  h3 {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 900;
    color: #5c4738;
  }
}

.section-icon {
  color: #c8955c;
}

.resource-row {
  margin-bottom: 16px;
}

.warehouse-footer {
  margin-top: 20px;
  padding-top: 16px;
  border-top: 2px dashed #e4d4ba;
}

.warehouse-lv {
  margin: 0 0 6px;
  font-size: 0.82rem;
  font-weight: 900;
  color: #5c4738;
}

.warehouse-cost {
  margin: 0 0 12px;
  font-size: 0.72rem;
  font-weight: 800;
  color: #d9776c;
  line-height: 1.45;

  &.enough {
    color: #4a7c59;
  }

  &.maxed {
    color: #8c7462;
  }
}

.warehouse-btn-wrap {
  display: flex;
  gap: 10px;
}

.warehouse-upgrade-btn {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 12px 10px;
  font-size: 0.88rem;
  white-space: nowrap;

  &:disabled {
    opacity: 0.45;
    cursor: not-allowed;
    transform: none;
    box-shadow: 0 4px 0 #5b8266;
  }
}

.warehouse-btn {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: #e6b981;
  color: #5c4738;
  border: 2px solid #c8955c;
  border-radius: 12px;
  font-weight: 900;
  font-family: inherit;
  padding: 12px 24px;
  cursor: pointer;
  box-shadow: 0 4px 0 #c8955c;
  transition: all 0.15s;

  &:hover {
    transform: translateY(2px);
    box-shadow: 0 2px 0 #c8955c;
  }

  &:active {
    transform: translateY(4px);
    box-shadow: none;
  }
}

.defense-card {
  display: flex;
  align-items: center;
}

.defense-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  width: 100%;
}

.defense-info {
  display: flex;
  align-items: center;
  gap: 14px;
}

.defense-icon {
  color: #8c7462;
  flex-shrink: 0;
}

.defense-lv {
  font-size: 1.5rem;
  font-weight: 900;
  color: #5c4738;
  margin: 4px 0 0;
}

.defense-cost {
  margin: 6px 0 0;
  font-size: 0.72rem;
  font-weight: 800;
  color: #d9776c;

  &.enough {
    color: #4a7c59;
  }
}

.defense-btn {
  padding: 10px 18px;
  white-space: nowrap;

  &:disabled {
    opacity: 0.45;
    cursor: not-allowed;
    transform: none;
    box-shadow: 0 4px 0 #5b8266;
  }
}

.building-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 20px;
}

.building-tag {
  background: #fdfbf7;
  border: 2px solid #d4c2a4;
  padding: 8px 14px;
  border-radius: 12px;
  font-size: 0.85rem;
  font-weight: 900;
  color: #6b4c3a;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
}

.btn-row {
  display: flex;
  gap: 10px;

  button {
    flex: 1;
    padding: 12px 8px;
    font-size: 0.88rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
  }
}

.modal-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 18px;

  h3 {
    margin: 0;
    font-weight: 900;
    font-size: 1.35rem;
    color: #5c4738;
  }

  .accent {
    color: #c8955c;
  }
}

.wide {
  max-width: 640px;
}

.item-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.warehouse-sections {
  flex: 1 1 auto;
  min-height: 0;
  padding-right: 4px;
}

.warehouse-section {
  margin-bottom: 20px;

  &:last-child {
    margin-bottom: 0;
  }
}

.warehouse-section-title {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 10px;
  font-size: 1rem;
  font-weight: 900;
  color: #5c4738;
  border-bottom: 2px solid rgba(200, 149, 92, 0.35);
  padding-bottom: 6px;
}

.warehouse-section-icon {
  font-size: 1.1rem;
}

.warehouse-section-total {
  margin-left: auto;
  font-size: 0.72rem;
  font-weight: 800;
  color: #a88a6d;
}

.warehouse-subsection {
  margin-bottom: 14px;
}

.warehouse-subsection-label {
  margin: 0 0 8px;
  font-size: 0.78rem;
  font-weight: 900;
  letter-spacing: 0.06em;
  color: #8c7462;
}

.item-card {
  background: #fcf8f0;
  border: 2px solid #e4d4ba;
  border-radius: 12px;
  padding: 16px;
  text-align: center;
  transition: all 0.2s;

  &:hover {
    border-color: #c8955c;
    transform: scale(1.03);
  }
}

.item-icon {
  font-size: 2.2rem;
  display: block;
  margin-bottom: 8px;
}

.item-name {
  font-weight: 900;
  font-size: 0.82rem;
  color: #5c4738;
  display: block;
}

.item-grade-tag {
  display: inline-block;
  margin-top: 4px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 0.65rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  border: 1px solid currentColor;
}

.grade-mat-common {
  color: #757575;
  background: rgba(158, 158, 158, 0.12);
}

.grade-mat-normal {
  color: #388e3c;
  background: rgba(102, 187, 106, 0.14);
}

.grade-mat-uncommon {
  color: #8e24aa;
  background: rgba(171, 71, 188, 0.12);
}

.grade-mat-rare {
  color: #ef6c00;
  background: rgba(251, 140, 0, 0.14);
}

.grade-mat-legendary {
  color: #f9a825;
  background: rgba(253, 216, 53, 0.18);
}

.item-qty {
  font-size: 0.7rem;
  font-weight: 900;
  color: #a88a6d;
  background: #f4ecdb;
  padding: 2px 6px;
  border-radius: 4px;
  margin-top: 6px;
  display: inline-block;
}

.w-full {
  width: 100%;
  padding: 14px;
}

.plan-modal {
  width: min(100%, 560px);
}

.plan-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-bottom: 12px;
}

.plan-tab {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 12px;
  border: 2px solid #8c7462;
  border-radius: 12px;
  background: #fcf8f0;
  font-weight: 900;
  font-size: 0.85rem;
  color: #6b4c3a;
  cursor: pointer;
  font-family: inherit;

  &.active {
    border-color: #4a7c59;
    background: #e8f3eb;
    color: #3d5c45;
  }
}

.plan-detail {
  flex: 1 1 auto;
  min-height: 0;
  border: 2px dashed #e4d4ba;
  border-radius: 14px;
  background: #fcf8f0;
  padding: 14px;
  margin-bottom: 14px;
}

.catalog-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
  margin-top: 10px;
}

@media (max-width: 520px) {
  .catalog-grid {
    grid-template-columns: 1fr;
  }
}

.plan-info {
  h4 {
    margin: 0 0 10px;
    font-size: 0.95rem;
    font-weight: 900;
    color: #3d5c45;
  }
}

.info-row {
  margin: 6px 0;
  font-size: 0.78rem;
  font-weight: 700;
  color: #5c4738;
  line-height: 1.45;

  span {
    font-weight: 900;
    color: #4a7c59;
    margin-right: 6px;
  }
}

.form-field.compact {
  margin-bottom: 10px;
}

.plan-confirm {
  margin-top: 0;

  &:disabled {
    opacity: 0.45;
    cursor: not-allowed;
  }
}

.plan-preview {
  background: #f4ecdb;
  border: 2px dashed #c8955c;
  border-radius: 12px;
  padding: 14px;
  margin-bottom: 16px;
}

.plan-preview-title {
  margin: 0 0 10px;
  font-size: 0.82rem;
  font-weight: 900;
  color: #5c4738;
}

.plan-preview-row {
  display: flex;
  gap: 10px;
  margin: 6px 0;
  font-size: 0.85rem;
  font-weight: 700;
  color: #6b4c3a;
}

.plan-preview-label {
  flex-shrink: 0;
  font-weight: 900;
  color: #8c7462;
  min-width: 2.5em;
}

.plan-preview-hint {
  margin: 10px 0 0;
  font-size: 0.72rem;
  font-weight: 800;
  color: #4a7c59;

  &.shortage {
    color: #d9776c;
  }
}

.materials-box {
  background: #fdf6e8;
  border-color: #c8955c;
}

.hours-box {
  background: #eef0f5;
  border-color: #8c7462;
}

.facility-modal {
  width: min(100%, 720px);
  position: relative;
  overflow: hidden;
  padding-top: 18px;
  padding-bottom: 18px;
}

.facility-layout {
  display: flex;
  align-items: stretch;
  flex: 1 1 auto;
  min-height: 0;
  flex-shrink: 1;
  overflow: hidden;
}

.facility-list {
  width: 50%;
  padding-right: 14px;
  border-right: 2px dashed #e4d4ba;
  overflow-y: auto;

  h3 {
    font-size: 1.2rem;
    font-weight: 900;
    margin: 0 0 14px;
    color: #5c4738;
    display: flex;
    align-items: center;
    gap: 8px;
  }
}

.facility-item {
  display: block;
  width: 100%;
  text-align: left;
  padding: 14px;
  margin-bottom: 8px;
  border: 2px solid #d4c2a4;
  border-radius: 12px;
  background: #fcf8f0;
  font-family: inherit;
  font-weight: 900;
  color: #4a3b32;
  cursor: pointer;
  transition: background 0.15s;

  &:hover {
    background: #fffdf8;
  }

  &.active {
    background: #f4ecdb;
    border-color: #c8955c;
  }
}

.facility-detail {
  width: 50%;
  padding-left: 20px;
  overflow: hidden;

  h4 {
    font-size: 1.3rem;
    font-weight: 900;
    color: #4a3b32;
    margin: 0 0 10px;
    padding-top: 0;
  }
}

.detail-box {
  background: #fcf8f0;
  border: 2px solid #e4d4ba;
  border-radius: 12px;
  padding: 12px;
  margin-bottom: 12px;

  p {
    margin: 0;
    font-weight: 700;
    color: #8c7462;
    font-size: 0.88rem;
    line-height: 1.5;
  }
}

.effect-box {
  margin-top: 12px;
  background: #eef5ef;
  border: 1px solid #7ca982;
  border-radius: 8px;
  padding: 10px;
  font-weight: 700;
  font-size: 0.85rem;
  color: #5c4738;

  .effect-label {
    display: block;
    font-size: 0.68rem;
    font-weight: 900;
    color: #4a7c59;
    margin-bottom: 4px;
  }
}

.facility-actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-top: 10px;
  border-top: 2px dashed #e4d4ba;

  .actions-label {
    font-size: 0.82rem;
    font-weight: 900;
    color: #8c7462;
  }

  button {
    padding: 10px;
    font-size: 0.88rem;
  }
}

.facility-empty {
  width: 50%;
  padding-left: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  color: #a88a6d;
  font-weight: 700;

  .empty-icon {
    opacity: 0.2;
    margin-bottom: 16px;
  }
}

.empty-hint {
  text-align: center;
  color: #8c7462;
  font-weight: 700;
  padding: 20px;
}

@container camp-panel (max-width: 519px) {
  .camp-layout {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .facility-layout {
    flex-direction: column;
  }

  .facility-list,
  .facility-detail,
  .facility-empty {
    width: 100%;
    border-right: none;
    padding: 0;
  }

  .facility-list {
    border-bottom: 2px dashed #e4d4ba;
    padding-bottom: 16px;
    margin-bottom: 16px;
  }
}
